/**
 * Tier C: the printed map, drawn in 2D. Shows all four map elements (title, key,
 * compass, scale) because Mission 1 teaches them. Features come from the content pack,
 * so a different pack draws a different map with no code change.
 */
import type { GeoPermissibleObjects } from "d3-geo";
import { useMemo } from "react";
import type { ContentPack, Feature, Locale } from "@dunialab/content";
// Regional cut of world-atlas 50m, generated by scripts/build-basemap.mjs (~65 KB instead of ~750 KB).
import basemap from "../assets/basemap.json";
import { t } from "../lib/packs.js";
import { isHomeBoundary } from "../lib/map-home.js";
import { createMapProjection } from "../lib/projection.js";

const W = 640;
const H = 720;
const PAD = 24;

const countries = (basemap as unknown as { features: (GeoPermissibleObjects & { id: string })[] }).features;

interface Props {
  pack: ContentPack;
  locale: Locale;
  /** Feature the child is being asked to find; highlighted only after answering. */
  revealId?: string | null;
  onFeatureTap?: (f: Feature) => void;
}

export function KenyaMap({ pack, locale, revealId, onFeatureTap }: Props) {
  const { path, project, scaleBar } = useMemo(
    () => createMapProjection(pack.printTarget.bounds, [[PAD, PAD + 40], [W - PAD, H - PAD - 60]]),
    [pack],
  );

  return (
    <svg className="map" viewBox={`0 0 ${W} ${H}`} role="img" aria-label={t(pack.title, locale)}>
      <rect x="0" y="0" width={W} height={H} className="sea" />
      {countries.map((c, i) => (
        <path key={i} d={path(c) ?? ""} className={isHomeBoundary(c.id, pack) ? "land home" : "land"} />
      ))}

      {/* Title */}
      <text x={W / 2} y={34} textAnchor="middle" className="map-title">
        {t(pack.title, locale)}: {locale === "sw" ? "Sura za Nchi" : "Physical Features"}
      </text>

      {/* Lines first (rivers, valley), then point features on top */}
      {pack.features.filter((f) => f.path).map((f) => (
        <path
          key={`${f.id}-line`}
          d={`M${f.path!.map((p) => project(p).join(",")).join("L")}`}
          className={`line ${f.kind} ${revealId === f.id ? "reveal" : ""}`}
          onClick={() => onFeatureTap?.(f)}
        />
      ))}
      {pack.features.map((f) => {
        const [x, y] = project(f.anchor);
        return (
          <g
            key={f.id}
            transform={`translate(${x},${y})`}
            className={`feature ${f.kind} ${revealId === f.id ? "reveal" : ""}`}
            onClick={() => onFeatureTap?.(f)}
            role="button"
            tabIndex={0}
            aria-label={t(f.name, locale)}
            onKeyDown={(e) => (e.key === "Enter" || e.key === " ") && onFeatureTap?.(f)}
          >
            <circle r="22" className="hit" />
            <Glyph kind={f.kind} />
            <text
              x={f.kind === "coast" ? 16 : 0}
              y={f.kind === "city" ? -10 : f.kind === "coast" ? 4 : 30}
              textAnchor={f.kind === "coast" ? "start" : "middle"}
              className="label"
            >
              {t(f.name, locale)}
            </text>
          </g>
        );
      })}

      {/* Compass */}
      <g transform={`translate(${W - 56},${96})`} className="compass" aria-label="compass">
        <circle r="26" />
        <path d="M0,-22 L7,0 L0,-5 L-7,0 Z" className="north" />
        <path d="M0,22 L7,0 L0,5 L-7,0 Z" />
        <text y="-30" textAnchor="middle">{locale === "sw" ? "K" : "N"}</text>
      </g>

      {/* Scale */}
      <g transform={`translate(${W - PAD - scaleBar.px},${H - 36})`} className="scale" aria-label="scale">
        <rect width={scaleBar.px / 2} height="6" className="dark" />
        <rect x={scaleBar.px / 2} width={scaleBar.px / 2} height="6" />
        <text x="0" y="22">0</text>
        <text x={scaleBar.px} y="22" textAnchor="end">{scaleBar.km} km</text>
      </g>

      {/* Key */}
      <g transform={`translate(${PAD},${H - 92})`} className="key" aria-label="key">
        <rect width="190" height="78" rx="6" />
        <text x="10" y="18" className="key-title">{locale === "sw" ? "Ufunguo" : "Key"}</text>
        <g transform="translate(20,34)"><Glyph kind="mountain" /></g>
        <text x="36" y="38">{locale === "sw" ? "Mlima" : "Mountain"}</text>
        <g transform="translate(110,34)"><Glyph kind="lake" /></g>
        <text x="126" y="38">{locale === "sw" ? "Ziwa" : "Lake"}</text>
        <line x1="12" y1="58" x2="30" y2="58" className="line river" />
        <text x="36" y="62">{locale === "sw" ? "Mto" : "River"}</text>
        <g transform="translate(110,58)"><Glyph kind="city" /></g>
        <text x="126" y="62">{locale === "sw" ? "Mji" : "Town"}</text>
      </g>
    </svg>
  );
}

function Glyph({ kind }: { kind: Feature["kind"] }) {
  switch (kind) {
    case "mountain":
      return <path d="M-9,7 L0,-9 L9,7 Z" className="g-mountain" />;
    case "lake":
      return <ellipse rx="10" ry="7" className="g-lake" />;
    case "city":
      return <circle r="4" className="g-city" />;
    case "coast":
    case "ocean":
      return <path d="M-10,0 q5,-6 10,0 t10,0" className="g-coast" />;
    default:
      return <circle r="5" className="g-other" />;
  }
}
